//! Records which source tree the binary was built from.
//!
//! The workspace version answers "how far upstream has been tracked" and is
//! deliberately not bumped for fixes, so it cannot tell two builds apart. A
//! corpus generated by the wrong build is not detectably wrong afterwards —
//! the records look the same — so the identity has to be in the binary and in
//! every run's first log line, not reconstructed later from a checksum.

use std::process::Command;

fn main() {
    println!("cargo:rustc-env=ATTIC_GENSFEN_BUILD={}", describe());

    // Without these the build script is cached and the recorded commit goes
    // stale on the next checkout. `.git` may be a file (a worktree points at
    // the real directory through one), in which case Cargo just watches that.
    for path in ["../../.git/HEAD", "../../.git/index"] {
        if std::path::Path::new(path).exists() {
            println!("cargo:rerun-if-changed={path}");
        }
    }
}

/// `<short sha>` for a clean tree, `<short sha>-dirty` when it is not, and
/// `unknown` when git cannot answer — the cluster builds from a copied tree
/// that may carry no `.git`, and a missing commit must not fail the build.
fn describe() -> String {
    let Some(sha) = git(&["rev-parse", "--short=8", "HEAD"]) else {
        return "unknown".to_string();
    };
    // `--quiet` makes the exit status the whole answer: 1 when the tree has
    // changes. A failure to run it at all is reported as dirty, because
    // claiming a clean tree that was never checked is the wrong way to be
    // wrong here.
    let clean = Command::new("git")
        .args(["diff", "--quiet", "HEAD"])
        .status()
        .map(|status| status.success())
        .unwrap_or(false);
    if clean { sha } else { format!("{sha}-dirty") }
}

fn git(args: &[&str]) -> Option<String> {
    let output = Command::new("git").args(args).output().ok()?;
    if !output.status.success() {
        return None;
    }
    let text = String::from_utf8(output.stdout).ok()?;
    let text = text.trim().to_string();
    (!text.is_empty()).then_some(text)
}
